public class Main {
    static String displayName(String name) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("Name is required");
        return name.strip();
    }
    public static void main(String[] args) {
        int runtimeFeature = Runtime.version().feature();
        if (runtimeFeature < 17) throw new IllegalStateException("Unsupported runtime baseline");
        if (!displayName("  CodeLeaf  ").equals("CodeLeaf")) throw new AssertionError("Regression detected");
        System.out.println("Runtime feature: " + runtimeFeature + "; regression check passed");
    }
}
